# MONGO DATABASE CONNECTION
MONGO_DB_NAME = os.environ.get("MONGO_DB", "tracker")
MONGO_DB_HOST = os.environ.get("MONGO_HOST", "mongo")
MONGO_DB_USERNAME = os.environ.get("MONGO_USER", "tracker")
MONGO_DB_PASSWORD = os.environ.get("MONGO_PASSWORD", "trackerlocal")
MONGO_DB_PORT = int(os.environ.get("MONGO_PORT", "27017"))

# Same reason as backend/tracker/settings.py: djongo memoises one MongoClient
# per database and its _close() closes that shared client, so a per-request
# close makes the NEXT request reopen a dead client and wait out pymongo's
# 0.5s rescan floor. Kept identical here so the two Django projects do not
# drift.
_CONN_MAX_AGE = os.environ.get("DB_CONN_MAX_AGE", "600").strip()
_MONGO_POOL = os.environ.get("MONGO_MAX_POOL_SIZE", "100").strip()
_MONGO_MAX_POOL = int(_MONGO_POOL) if _MONGO_POOL.isdigit() else 100

DATABASES = {
    'default': {
        'ENGINE': 'djongo',
        'ENFORCE_SCHEMA': False,
        'CONN_MAX_AGE': int(_CONN_MAX_AGE) if _CONN_MAX_AGE.isdigit() else 600,
        'LOGGING': {
            'version': 1,
            'loggers': {
                'djongo': {
                    'level': 'DEBUG',
                    'propogate': False,                        
                } 
            },
         }, 
        'NAME': MONGO_DB_NAME,
        'CLIENT': {
            'host': MONGO_DB_HOST, 
            'port': MONGO_DB_PORT,
            'username': MONGO_DB_USERNAME,
            'password': MONGO_DB_PASSWORD, 
            'authSource': os.environ.get("MONGO_AUTH_SOURCE", MONGO_DB_NAME),
            'authMechanism': 'SCRAM-SHA-1',
            # One connection per thread, kept open by CONN_MAX_AGE, so this
            # must exceed ENGINE_THREADS.
            'maxPoolSize': _MONGO_MAX_POOL,
        }
    }
} 

mongoengine.connect(
    db=MONGO_DB_NAME,
    host=MONGO_DB_HOST,
    username=MONGO_DB_USERNAME,
    password=MONGO_DB_PASSWORD,
    authentication_source=os.environ.get("MONGO_AUTH_SOURCE", MONGO_DB_NAME),
    port=MONGO_DB_PORT,        
) 


