# These were written with ':' not '=' -- annotations, which bind no module
# attribute at all. Django's own defaults happened to match, so nothing broke,
# but any value set here was silently ignored.
EMAIL_BACKEND = 'django.core.mail.backends.smtp.EmailBackend'

EMAIL_USE_SSL = False
EMAIL_HOST = os.environ.get("EMAIL_HOST", "localhost")
EMAIL_HOST_USER = os.environ.get("EMAIL_HOST_USER", "")
EMAIL_HOST_PASSWORD = os.environ.get("EMAIL_HOST_PASSWORD", "")
EMAIL_PORT = int(os.environ.get("EMAIL_PORT", "25"))
EMAIL_USE_TLS = False
TRIAL_DAYS = 14

EMERGENCY_MAIL = os.environ.get("EMERGENCY_MAIL", "") 

CORE_SUBJECT_ALERT = "SearchMirror WatchDog Alert"

MAIL_TOKEN = os.environ.get("ENGINE_MAIL_TOKEN", "")

SITE_URL = os.environ.get("APP_API_URL", "http://backend:8000").rstrip("/")

API_GOOGLE_LINK = "/spyglass/notify" 

# THE SESSION URL TO SPLIT THE URL AND KEYWORD ID.
URL_DELIMITER = "~_~" 

# PROXY MAXIMUM FAILURES ALERT
DEFAULT_MAX_PROXY_LOAD_LIMIT = 500 

# Default primary key field type
# https://docs.djangoproject.com/en/3.2/ref/settings/#default-auto-field

DEFAULT_AUTO_FIELD = 'django.db.models.BigAutoField'
DATABLUE_API_KEY = os.environ.get("DATABLUE_API_KEY", "")

# Whether a fetch with no per-account key may spend DATABLUE_API_KEY above.
# True suits a single-operator self-host running everything on one key. Set it
# false for a hosted instance: there, an account with no readable key must get
# NO ranking rather than quietly billing the house key.
ALLOW_INSTANCE_FALLBACK = os.environ.get("ALLOW_INSTANCE_FALLBACK", "false")
